import confetti,{create,}from"https://cdn.jsdelivr.net/npm/canvas-confetti@0.2.0-beta0/dist/confetti.module.mjs";class ConfettiCheckboxes extends HTMLElement{constructor(){super(),this.attachShadow({mode:"open"}),this.shadowRoot.innerHTML=`
            <style>
                .confetti {
                    position: fixed;
                    top: 0;
                    left: 0;
                    width: 100%;
                    height: 100%;
                    z-index: 9999;
                    pointer-events: none;
                }
            </style>
            <slot></slot>
            <canvas id="confetti" class="confetti"></canvas>
        `,this.confettiCanvas=this.shadowRoot.getElementById("confetti"),this.checkboxes=this.querySelectorAll('input[type="checkbox"]'),this.allChecked=!1,this.addCheckboxListeners(),this.initialiseCheckboxValues()}initialiseCheckboxValues(){this.checkboxes.forEach((e,t)=>{const n=localStorage.getItem(`confetti-checks-${window.location.pathname}-${t}`);e.checked=n==="true"})}addCheckboxListeners(){this.checkboxes.forEach((e,t)=>{e.addEventListener("change",()=>{localStorage.setItem(`confetti-checks-${window.location.pathname}-${t}`,e.checked),this.allChecked=Array.from(this.checkboxes).every(e=>e.checked),this.allChecked?(this.triggerConfetti(),this.updateAnnouncer("Well done! You've completed all the objectives!")):this.updateAnnouncer("")})})}triggerConfetti(){confetti.create(this.confettiCanvas,{resize:!0,useWorker:!0})({particleCount:200,spread:170})}updateAnnouncer(e){this.querySelector("#announcer").textContent=e}}customElements.define("confetti-checkboxes",ConfettiCheckboxes)